{"implementation": "def solve(case):
    payload = case['payload']
    initial_state = payload['initial_state']
    max_steps = payload['max_steps']
    tool_observations = payload['tool_observations']
    transitions = payload['transitions']

    if initial_state not in transitions:
        return {'status': 'invalid_state', 'final_value': None, 'trace': []}

    current_state = initial_state
    steps = 0
    trace = []

    # Check if already final
    if transitions[current_state]['kind'] == 'final':
        return {'status': 'completed', 'final_value': transitions[current_state]['value'], 'trace': []}

    while steps < max_steps:
        node = transitions.get(current_state)
        if node is None:
            return {'status': 'invalid_state', 'final_value': None, 'trace': trace}
        if node['kind'] == 'final':
            break
        # action state
        action = node['action']
        if action in tool_observations:
            observation = tool_observations[action]
        else:
            observation = 'tool_not_found'
        next_by_obs = node.get('next_by_observation', {})
        if observation in next_by_obs:
            next_state = next_by_obs[observation]
        else:
            next_state = node.get('default_next')
        if next_state is None:
            return {'status': 'invalid_transition', 'final_value': None, 'trace': trace}
        trace.append({
            'state': current_state,
            'action': action,
            'observation': observation,
            'next_state': next_state
        })
        current_state = next_state
        steps += 1
        # After moving, check if new state is final
        if current_state in transitions and transitions[current_state]['kind'] == 'final':
            break
    else:
        # Loop ended because steps == max_steps without reaching final
        if current_state in transitions and transitions[current_state]['kind'] == 'final':
            # Actually we might have broken on final in the last iteration before increment? The break inside loop catches final after step.
            # But the while condition fails after increment, so this else won't trigger if we broke.
            pass
        else:
            return {'status': 'max_steps_exceeded', 'final_value': None, 'trace': trace}

    # Determine final status and value
    if current_state in transitions and transitions[current_state]['kind'] == 'final':
        final_value = transitions[current_state]['value']
        return {'status': 'completed', 'final_value': final_value, 'trace': trace}
    else:
        return {'status': 'max_steps_exceeded', 'final_value': None, 'trace': trace}"}
